return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'te','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'ఈ సైట్ యొక్క మీడియా లైబ్రరీని Zinn® ఆబ్జెక్ట్ స్టోరేజ్‌కి మారుస్తుంది మరియు CDN నుండి అందిస్తుంది. మీ Zinn® డాష్‌బోర్డ్ నుండి కాన్ఫిగర్ చేయబడింది — WordPressలో ఏ యాక్సెస్ కీ టైప్ చేయబడదు.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'నిల్వ చేయబడింది. దాన్ని భర్తీ చేయడానికి కొత్త విలువను టైప్ చేయండి.','Filter this list…'=>'ఈ జాబితాను ఫిల్టర్ చేయండి…','Filter this list'=>'ఈ జాబితాను ఫిల్టర్ చేయండి','Nothing matches that filter.'=>'ఆ ఫిల్టర్‌కు సరిపోయేది ఏదీ లేదు.','Add a row'=>'ఒక వరుసను జోడించు','Remove this row'=>'ఈ అడ్డు వరుసను తీసివేయి','Remove'=>'తీసివేయి','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — అవలోకనం','Overview'=>'అవలోకనం','Every Zinn® plugin on this site, and whether it is working.'=>'ఈ సైట్‌లోని ప్రతి Zinn® ప్లగ్-ఇన్ మరియు అది పని చేస్తుందా లేదా అనేది.','No connection is needed for this plugin.'=>'ఈ ప్లగిన్ కోసం ఎలాంటి కనెక్షన్ అవసరం లేదు.','Open settings'=>'సెట్టింగ్‌లను తెరువు','You do not have permission to change these settings.'=>'ఈ సెట్టింగ్‌లను మార్చడానికి మీకు అనుమతి లేదు.','Settings sections'=>'సెట్టింగ్‌ల విభాగాలు','Support'=>'మద్దతు','Save changes'=>'మార్పులను సేవ్ చేయి','Tools'=>'సాధనాలు','Export settings'=>'సెట్టింగ్‌లను ఎగుమతి చేయి','Reset to defaults'=>'డిఫాల్ట్‌లకు రీసెట్ 